// Pull the queued topic, or stop the run cleanly if the calendar is empty.
// Notion text-like properties wrap their value differently — handle both rich_text and title.
function text(prop) {
  if (!prop) return '';
  const arr = prop.title || prop.rich_text || [];
  return arr.map(t => t.plain_text).join('').trim();
}
function selectVal(prop) {
  return prop?.select?.name || '';
}

const config = $('Config').first().json;
const response = $input.first().json;
const results = response.results || [];

if (results.length === 0) {
  console.log('No queued topics in Notion calendar. Stopping run.');
  return [];
}

const page = results[0];
const props = page.properties || {};

const topic = text(props.Topic || props.Name || props.Title);
if (!topic) {
  throw new Error(`Topic page ${page.id} has no Topic/Name property text — fix the calendar entry.`);
}

// Optional fields — empty strings are fine, the prompt handles missing values.
const notes = text(props.Notes);
const targetKeyword = text(props['Target Keyword']);
const tag = selectVal(props.Tag);

return [{ json: {
  ...config,
  topicPageId: page.id,
  blogTopic: topic,
  topicNotes: notes,
  targetKeyword,
  primaryTag: tag,
}}];

// Deterministic sanitizer — catches LLM slop the prompt rules missed.
function sanitizeMdx(input) {
  let out = input;
  const svgAttrFixes = [
    [/textAnchor=/g, 'text-anchor='],
    [/fontWeight=/g, 'font-weight='],
    [/fontSize=/g, 'font-size='],
    [/fontFamily=/g, 'font-family='],
    [/strokeWidth=/g, 'stroke-width='],
    [/strokeDasharray=/g, 'stroke-dasharray='],
    [/strokeLinecap=/g, 'stroke-linecap='],
    [/strokeLinejoin=/g, 'stroke-linejoin='],
    [/markerEnd=/g, 'marker-end='],
    [/markerStart=/g, 'marker-start='],
    [/clipPath=/g, 'clip-path='],
    [/fillOpacity=/g, 'fill-opacity='],
    [/strokeOpacity=/g, 'stroke-opacity='],
  ];
  for (const [pattern, replacement] of svgAttrFixes) {
    out = out.replace(pattern, replacement);
  }
  // Em dash (U+2014) and en dash (U+2013) → comma+space (preserves sentence flow).
  out = out.replace(/ \u2014 /g, ', ').replace(/\u2014/g, ', ');
  out = out.replace(/ \u2013 /g, ', ').replace(/\u2013/g, ', ');
  // Old dark-theme diagram colors -> light cream/teal/ink palette. The site flipped to light; the engine still learned the dark palette, so remap deterministically.
  const colorFixes = [
    [/#6366f1/gi, '#14a890'],
    [/#4f46e5/gi, '#0d8c78'],
    [/#4338ca/gi, '#0d8c78'],
    [/#818cf8/gi, '#14a890'],
    [/#a5b4fc/gi, '#e6fbf6'],
    [/#c7d2fe/gi, '#e6fbf6'],
    [/#e0e7ff/gi, '#e6fbf6'],
    [/#eef2ff/gi, '#e6fbf6'],
    [/#0f172a/gi, '#262b32'],
    [/#1e293b/gi, '#262b32'],
    [/#334155/gi, '#262b32'],
    [/#475569/gi, '#5e6671'],
    [/#e2e8f0/gi, '#f6f4ec'],
    [/#f1f5f9/gi, '#f6f4ec'],
    [/#aaaaaa/gi, '#cdc7b3'],
    [/#aaa\b/gi, '#cdc7b3'],
  ];
  for (const [pattern, replacement] of colorFixes) {
    out = out.replace(pattern, replacement);
  }
  return out;
}

// Take the humanized MDX draft, extract the title, build a slug + filename + branch name.
// Outputs both filePath (.mdx, canonical) and filePathMd (.md, legacy idempotency check).
const response = $input.first().json;
const topic = $('Parse Topic').first().json;

if (!response.content || !Array.isArray(response.content) || !response.content[0]?.text) {
  throw new Error('Humanize response malformed: ' + JSON.stringify(response).substring(0, 500));
}

const markdown = sanitizeMdx(response.content[0].text.trim());

if (!markdown.startsWith('---')) {
  throw new Error('Generated MDX missing frontmatter block. First 200 chars: ' + markdown.substring(0, 200));
}

const titleMatch = markdown.match(/^---[\s\S]*?^title:\s*["']?(.+?)["']?\s*$/m);
if (!titleMatch) {
  throw new Error('Could not parse title from frontmatter.');
}
const title = titleMatch[1].trim().replace(/^"|"$/g, '').replace(/^'|'$/g, '');

// Sanity check: import block must be present.
if (!markdown.includes("import SideBySide from '@/components/post/SideBySide.astro'")) {
  throw new Error('MDX missing required component imports. Engine prompt may be drifting — review Generate Draft output.');
}

const slug = title.toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .substring(0, 60)
  .replace(/-$/, '');

const today = new Date().toISOString().split('T')[0];
const filename = `${today}-${slug}.mdx`;
const filePath = `src/content/blog/${filename}`;
const filePathMd = `src/content/blog/${today}-${slug}.md`; // legacy collision check

const branchName = `content/${today}-${slug}`;
const encodedContent = Buffer.from(markdown).toString('base64');

return [{ json: {
  ...topic,
  markdown,
  title,
  slug,
  filename,
  filePath,
  filePathMd,
  branchName,
  encodedContent,
  pubDate: today,
}}];

// Verify BOTH the .mdx and the legacy .md path don't already exist on master.
// If either returns 200, abort — we already published this slug.
const draft = $('Parse Draft').first().json;
const mdxResp = $('Check Idempotency MDX').first().json;
const mdResp = $input.first().json; // most recent: Check Idempotency MD

if (mdxResp.statusCode === 200) {
  throw new Error(`Post already exists at .mdx path: ${draft.filePath}. Skipping to avoid overwrite.`);
}
if (mdResp.statusCode === 200) {
  throw new Error(`Post already exists at legacy .md path: ${draft.filePathMd}. Skipping to avoid overwrite.`);
}
if (mdxResp.statusCode !== 404) {
  throw new Error(`Unexpected GitHub status ${mdxResp.statusCode} on .mdx idempotency check. Body: ${JSON.stringify(mdxResp.body).substring(0, 300)}`);
}
if (mdResp.statusCode !== 404) {
  throw new Error(`Unexpected GitHub status ${mdResp.statusCode} on .md idempotency check. Body: ${JSON.stringify(mdResp.body).substring(0, 300)}`);
}

console.log(`Both ${draft.filePath} and ${draft.filePathMd} are absent on ${draft.githubBaseBranch} — safe to commit.`);
return [{ json: draft }];

// Carry the base SHA forward and merge it with the draft payload.
const draft = $('Confirm Not Exists').first().json;
const sha = $input.first().json?.object?.sha;
if (!sha) {
  throw new Error('Could not read base branch SHA from GitHub response.');
}
return [{ json: { ...draft, baseSha: sha } }];

